components.css:
.ds-btn-primary {
  display: inline-block;
  padding: 10px 20px;
  border-radius: 6px;
  border: none;
  background: #1e3a5f;
  color: #fff;
  font: 600 14px/1.3 system-ui, 'Segoe UI', Roboto, sans-serif;
  letter-spacing: 0.03em;
  cursor: pointer;
  transition: background 0.2s ease, opacity 0.2s ease;
}
.ds-btn-primary:hover {
  background: #162d4a;
}
.ds-btn-primary:focus-visible {
  outline: 2px solid rgba(30, 58, 95, 0.5);
  outline-offset: 2px;
}
.ds-btn-primary:disabled {
  opacity: 0.6;
  cursor: not-allowed;
}

.ds-btn-secondary {
  display: inline-block;
  padding: 10px 20px;
  border-radius: 6px;
  border: 1px solid #e5e4e7;
  background: transparent;
  color: #08060d;
  font: 600 14px/1.3 system-ui, 'Segoe UI', Roboto, sans-serif;
  cursor: pointer;
  transition: border-color 0.2s ease, opacity 0.2s ease;
}
.ds-btn-secondary:hover {
  border-color: #1e3a5f;
}
.ds-btn-secondary:focus-visible {
  outline: 2px solid rgba(30, 58, 95, 0.5);
  outline-offset: 2px;
}
.ds-btn-secondary:disabled {
  opacity: 0.6;
  cursor: not-allowed;
}

.ds-btn-danger {
  display: inline-block;
  padding: 10px 20px;
  border-radius: 6px;
  border: 1px solid #ef4444;
  background: transparent;
  color: #ef4444;
  font: 600 14px/1.3 system-ui, 'Segoe UI', Roboto, sans-serif;
  cursor: pointer;
  transition: background 0.2s ease, opacity 0.2s ease;
}
.ds-btn-danger:hover {
  background: rgba(239, 68, 68, 0.05);
}
.ds-btn-danger:focus-visible {
  outline: 2px solid rgba(239, 68, 68, 0.5);
  outline-offset: 2px;
}
.ds-btn-danger:disabled {
  opacity: 0.6;
  cursor: not-allowed;
}

.ds-input {
  width: 100%;
  padding: 10px 14px;
  border-radius: 6px;
  border: 1px solid #e5e4e7;
  background: #fff;
  color: #08060d;
  font: 400 15px/1.4 system-ui, 'Segoe UI', Roboto, sans-serif;
  box-sizing: border-box;
  transition: border-color 0.2s ease, box-shadow 0.2s ease;
}
.ds-input::placeholder {
  color: #6b6375;
}
.ds-input:focus {
  outline: none;
  border-color: #1e3a5f;
  box-shadow: 0 0 0 3px rgba(30, 58, 95, 0.1);
}

.ds-nav {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 16px 32px;
  border-bottom: 1px solid #e5e4e7;
  font-family: system-ui, 'Segoe UI', Roboto, sans-serif;
}
.ds-nav-brand {
  font-size: 24px;
  font-weight: 700;
  color: #1e3a5f;
  text-decoration: none;
}
.ds-nav-links {
  display: flex;
  gap: 20px;
}
.ds-nav-links a {
  color: #6b6375;
  text-decoration: none;
  font-size: 16px;
  transition: color 0.2s ease;
}
.ds-nav-links a:hover {
  color: #08060d;
}

.ds-badge {
  display: inline-block;
  padding: 2px 10px;
  border-radius: 12px;
  font: 600 13px/1.3 system-ui, 'Segoe UI', Roboto, sans-serif;
}
.ds-badge-ok {
  background: rgba(34, 197, 94, 0.15);
  color: #22c55e;
}
.ds-badge-overdue {
  background: rgba(239, 68, 68, 0.15);
  color: #ef4444;
  font-weight: 700;
}
.ds-badge-returned {
  background: rgba(107, 114, 128, 0.15);
  color: #6b7280;
}
.ds-badge-pending {
  background: rgba(251, 191, 36, 0.15);
  color: #f59e0b;
}
.ds-badge-empty {
  background: rgba(239, 68, 68, 0.1);
  color: #ef4444;
}

.ds-card {
  background: #f4f3ec;
  border-radius: 8px;
  padding: 24px;
  font-family: system-ui, 'Segoe UI', Roboto, sans-serif;
}
.ds-card-title {
  margin: 0 0 24px;
  font-size: 24px;
  font-weight: 500;
  line-height: 1.18;
  letter-spacing: -0.01em;
  color: #08060d;
}
.ds-card-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
}
.ds-card-field {
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.ds-card-label {
  font-size: 12px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: #6b6375;
}
.ds-card-value {
  font-size: 16px;
  color: #08060d;
}

.ds-stat-tile {
  background: #f4f3ec;
  border-radius: 10px;
  padding: 20px;
  border: 1px solid #e5e4e7;
  font-family: system-ui, 'Segoe UI', Roboto, sans-serif;
}
.ds-stat-title {
  font-size: 12px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: #6b6375;
  margin: 0 0 12px;
}
.ds-stat-value {
  font-size: 36px;
  font-weight: 800;
  line-height: 1.1;
  margin: 0;
}
